const body = items[0].json.body || items[0].json;
const data = body.data || {};

const alertSubject = `[URGENT RESCUE] ${data.animal_type || 'Animal'} reported at ${data.location || 'Unknown Location'}`;
const alertBody = `🚨 NEW RESCUE / SOS REPORT SUBMITTED\n\nReport ID: #${data.report_id}\nAnimal: ${data.animal_type || 'Unknown'} (${data.breed || 'Mixed Breed'})\nLocation: ${data.location}\nReporter: ${data.contact_name || 'Anonymous'} (Phone: ${data.contact_phone || 'N/A'}, Email: ${data.contact_email || 'N/A'})\nTime: ${data.submitted_at}\n\nPlease review in the Admin Rescue Management dashboard.`;

return [{
  json: {
    eventId: body.event_id,
    reportId: data.report_id,
    animalType: data.animal_type,
    location: data.location,
    reporterEmail: data.contact_email,
    alertSubject: alertSubject,
    alertBody: alertBody
  }
}];
